"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFeatureContent } from "./components/feature-sections/content";
import View8 from "./components/feature-sections/variants/09-list";
const variants = {"list":View8};
export type { ArtemisFeatureContent, ArtemisFeatureImage, ArtemisFeatureItem, ArtemisFeatureLink } from "./components/feature-sections/content";
export interface ArtemisFeatureSectionsProps { className?: string; variant?: "list"; /** The words on the feature section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFeatureContent>; }
export function ArtemisFeatureSections({ className, variant = "list", content }: ArtemisFeatureSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisFeatureLink {
  label: string;
  href: string;
}

/** A picture shown as content, and the words that stand in for it. */
export interface ArtemisFeatureImage {
  src: string;
  alt: string;
}

/** One feature: a row, card, step or tab, depending on the layout. */
export interface ArtemisFeatureItem {
  /** The feature's name. All layouts; signal-grid puts its first word on a line of its own. */
  title: string;
  /** A sentence or two about the feature. All layouts; product-hotspots, steps, tabs and stage-tabs show it for the chosen feature only. */
  description: string;
  /** A short name: the tab in tabs and stage-tabs (which show the title when you leave this out), and the words after the number in alternating-rows. */
  label?: string;
  /** Short points under the description. alternating-rows, product-hotspots and tabs. */
  bullets?: string[];
  /** A figure shown large. voice-ai (first card) and control-deck (third and fourth cards; on the third, a trailing % is set small and fills the bar). */
  stat?: string;
  /** The feature's icon. visual-benefits, signal-grid, voice-ai (first card), control-deck (fourth and fifth cards) and tabs, which keep their own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
  /** A product picture. tabs, which shows its own picture for that slot when you leave this out. */
  image?: ArtemisFeatureImage;
}

/**
 * The words on an Artemis feature section. Every layout reads this shape, so you can switch layouts and keep them.
 * An empty `badge`, `headlineAccent` or `subhead` leaves that line out.
 */
export interface ArtemisFeatureContent {
  /** A short line above the headline. All layouts except visual-benefits, alternating-rows and stage-tabs. */
  badge?: string;
  /** The section heading. All layouts except stage-tabs. */
  headline?: string;
  /**
   * The second part of the heading. showcase, signal-grid, control-deck, voice-ai, list, bento and tabs put it on a
   * line of its own, steps sets it in the accent color, and the other layouts with a heading run it on after the
   * headline. It goes with `headline`: give a headline without it and the heading has no second part.
   */
  headlineAccent?: string;
  /** A sentence or two under the heading. All layouts except visual-benefits, tabs and stage-tabs. */
  subhead?: string;
  /**
   * The features. All layouts. Today's counts look best: three in visual-benefits, alternating-rows, showcase,
   * benefits-triptych and steps; four in product-hotspots, voice-ai, list, tabs and stage-tabs; five in control-deck
   * (which shows no more than five) and bento; six in signal-grid.
   */
  items: ArtemisFeatureItem[];
  /** The button under the features. visual-benefits. */
  cta?: ArtemisFeatureLink;
}

"use client";
// @zeus-internal
import { AnimatePresence, motion, type Transition, useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import type { ArtemisFeatureContent } from "../content";
const DEFAULT = {
    badge: "Built to ship",
    headline: "Everything you need to ship",
    headlineAccent: "premium UI, nothing in your way.",
    subhead: "From primitive to shipped block in minutes \u2014 polished, animated, and ready to publish.",
    items: [
        { title: "Copy-paste source", description: "Own the code. Every component drops into your repo as real source \u2014 yours to read and edit." },
        { title: "Private registry", description: "Install premium components from your own namespace with a single shadcn CLI command." },
        { title: "Motion built-in", description: "Tuned springs, shared-layout transitions, and reduced-motion fallbacks ship with every piece." },
        { title: "Theme-aware", description: "Built on your tokens \u2014 every component reads correctly in light and dark out of the box." },
    ],
} satisfies ArtemisFeatureContent;
const ADVANCE_MS = 3600;
const WORD_HIDDEN = { opacity: 0, filter: "blur(10px)", y: "40%" };
const WORD_SHOWN = { opacity: 1, filter: "blur(0px)", y: 0 };
const WORD_STAGGER = 0.09;
const PANEL_SWAP: Transition = { duration: 0.32, ease: ARTEMIS_EASE_OUT };
const BUTTON_BASE = "art:items-center art:justify-center art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:h-auto art:p-0 art:font-normal art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:max-w-md art:text-left art:outline-none art:transition-opacity art:duration-300 art:focus-visible:opacity-100";
function wordTransition(index: number): Transition {
    const delay = index * WORD_STAGGER;
    return {
        opacity: { duration: 0.7, ease: ARTEMIS_EASE_OUT, delay },
        filter: { duration: 0.9, ease: ARTEMIS_EASE_OUT, delay },
        y: { type: "spring", stiffness: 140, damping: 26, mass: 1.2, delay },
    };
}
function useReducedAfterMount(): boolean {
    const prefers = useReducedMotion() ?? false;
    const [mounted, setMounted] = useState(false);
    useEffect(() => setMounted(true), []);
    return mounted && prefers;
}
function Word({ index, children }: {
    index: number;
    children: ReactNode;
}) {
    // Read on the first render, so the entrance is already instant with reduced motion; the start still matches the server.
    const reduce = useReducedMotion() === true;
    return (<motion.span className="art:inline-block art:will-change-transform" initial={WORD_HIDDEN} animate={WORD_SHOWN} transition={reduce ? { duration: 0 } : wordTransition(index)}>
      {children}
    </motion.span>);
}
function Check({ className }: {
    className: string;
}) {
    return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-check ${className}`} aria-hidden="true">
      <path d="M20 6 9 17l-5-5"/>
    </svg>);
}
function PanelContent({ index }: {
    index: number;
}) {
    if (index === 0) {
        return (<div className="art:rounded-2xl art:border art:border-border art:bg-background/90 art:p-4 art:backdrop-blur-md art:text-foreground">
        <div className="art:flex art:items-center art:justify-between">
          <span className="art:font-mono art:text-xs">{"pricing.tsx"}</span>
          <span className="art:inline-flex art:items-center art:gap-1.5 art:rounded-md art:bg-background/90 art:px-2 art:py-1 art:text-xs">
            <Check className="art:size-3"/>
            {" Copied"}
          </span>
        </div>
        <div className="art:mt-3 art:space-y-1.5">
          <div className="art:h-2 art:w-4/5 art:rounded-full art:bg-background/90"/>
          <div className="art:h-2 art:w-3/5 art:rounded-full art:bg-background/90"/>
          <div className="art:h-2 art:w-2/3 art:rounded-full art:bg-background/90"/>
        </div>
      </div>);
    }
    if (index === 1) {
        return (<div className="art:rounded-2xl art:border art:border-border art:bg-background/90 art:p-4 art:backdrop-blur-md art:font-mono art:text-foreground art:text-xs">
        <p className="art:text-foreground/55">{"$ npx shadcn add"}</p>
        <p className="art:mt-1 art:font-medium">{"@zeus/ui/pricing"}</p>
        <p className="art:mt-3 art:flex art:items-center art:gap-2 art:text-primary">
          <span className="art:grid art:size-3.5 art:place-items-center art:rounded-full art:bg-muted art:text-foreground">
            <Check className="art:size-2.5"/>
          </span>
          {"added 1 component"}
        </p>
      </div>);
    }
    if (index === 2) {
        return (<div className="art:rounded-2xl art:border art:border-border art:bg-background/90 art:p-4 art:backdrop-blur-md art:flex art:flex-col art:items-center art:gap-3">
        <span className="art:inline-flex art:h-10 art:items-center art:rounded-full art:bg-white art:px-6 art:font-medium art:text-neutral-900 art:text-sm">{"Get started"}</span>
        <span className="art:text-xs art:text-foreground/70">{"Spring press \u00B7 60fps"}</span>
      </div>);
    }
    return (<div className="art:rounded-2xl art:border art:border-border art:bg-background/90 art:p-4 art:backdrop-blur-md art:flex art:items-center art:gap-3">
      <div className="art:flex-1 art:rounded-xl art:border art:border-border art:bg-white art:p-3">
        <div className="art:h-2 art:w-2/3 art:rounded-full art:bg-neutral-300"/>
        <div className="art:mt-2 art:h-2 art:w-1/2 art:rounded-full art:bg-neutral-200"/>
        <p className="art:mt-2 art:text-xs art:text-neutral-500">{"Light"}</p>
      </div>
      <div className="art:flex-1 art:rounded-xl art:border art:border-border art:bg-background art:p-3">
        <div className="art:h-2 art:w-2/3 art:rounded-full art:bg-neutral-700"/>
        <div className="art:mt-2 art:h-2 art:w-1/2 art:rounded-full art:bg-neutral-800"/>
        <p className="art:mt-2 art:text-xs art:text-neutral-400">{"Dark"}</p>
      </div>
    </div>);
}
export default function FeatureSectionsList({ content }: { content?: Partial<ArtemisFeatureContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const lines = [copy.headline, accent].flatMap((text) => (text ? [text.split(/\s+/).filter(Boolean)] : []));
    const count = copy.items.length;
    const reduce = useReducedAfterMount();
    const [active, setActive] = useState(0);
    const [paused, setPaused] = useState(false);
    useEffect(() => {
        if (paused || reduce || count < 2)
            return;
        const id = setInterval(() => setActive((i) => (i + 1) % count), ADVANCE_MS);
        return () => clearInterval(id);
    }, [active, paused, reduce, count]);
    let wordIndex = 0;
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:mx-auto art:w-full art:max-w-6xl">
            <div className="art:max-w-2xl">
              {copy.badge ? <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest">{copy.badge}</p> : null}
              <h2 className="art:block art:mt-5 art:text-balance art:text-foreground art:tracking-tight art:text-4xl art:font-medium">
                {lines.map((line, li) => (<span key={li} className="art:block">
                    {line.map((word, i) => {
                const index = wordIndex++;
                return (<Word key={i} index={index}>
                          {word}
                          {i < line.length - 1 ? <span className="art:inline-block art:w-[0.25em] art:overflow-hidden">{"\u00A0"}</span> : null}
                        </Word>);
            })}
                  </span>))}
              </h2>
              {copy.subhead ? (<p className="art:mt-4 art:max-w-md art:text-pretty art:text-muted-foreground art:text-sm art:leading-7">
                {copy.subhead}
              </p>) : null}
            </div>
            <div className="art:mt-14 art:grid art:items-center art:gap-10 art:@min-[1024px]/artemis:grid-cols-2 art:@min-[1024px]/artemis:gap-14">
              <div className="art:flex art:flex-col art:gap-7">
                {copy.items.map((f, i) => (<motion.button key={f.title} type="button" className={`${BUTTON_BASE} ${i === active ? "art:opacity-100" : "art:opacity-40 art:hover:opacity-70"} art:rounded-full`} tabIndex={0} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} onMouseEnter={() => {
                setActive(i);
                setPaused(true);
            }} onMouseLeave={() => setPaused(false)} onClick={() => setActive(i)}>
                    <h3 className="art:font-medium art:text-foreground art:text-xl">{f.title}</h3>
                    <p className="art:mt-2 art:text-muted-foreground art:text-sm art:leading-7">{f.description}</p>
                  </motion.button>))}
              </div>
              <div className="art:relative art:h-[26rem] art:overflow-hidden art:rounded-2xl">
                <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:overflow-hidden">

                  <img src="/assets/artemis/67d0f288f8986ef4cdb4.webp" alt="" width="768" height="768" loading="lazy" decoding="async" className="art:size-full art:object-cover" style={{ objectPosition: "center" }}/>
                  <div className="art:absolute art:inset-0 art:bg-background/10 art:dark:bg-background/65"/>
                </div>
                <div className="art:absolute art:inset-0 art:grid art:place-items-center art:p-6">
                  <AnimatePresence mode="wait" initial={false}>
                    <motion.div key={active} className="art:w-full art:max-w-xs" initial={reduce ? false : { opacity: 0, filter: "blur(6px)", y: 14 }} animate={{ opacity: 1, filter: "blur(0px)", y: 0 }} exit={reduce ? { opacity: 1 } : { opacity: 0, y: -10 }} transition={reduce ? { duration: 0 } : PANEL_SWAP}>
                      <PanelContent index={active % 4}/>
                    </motion.div>
                  </AnimatePresence>
                </div>
              </div>
            </div>
          </div>
        </section>
      </div>
    </>);
}
